import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.C7GIOALF.js";const p=JSON.parse('{"title":"Everyday Life and Ordinary New York","description":"","frontmatter":{},"headers":[],"relativePath":"research/everyday-life.md","filePath":"research/everyday-life.md","lastUpdated":null}'),o={name:"research/everyday-life.md"};function n(i,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="everyday-life-and-ordinary-new-york" tabindex="-1">Everyday Life and Ordinary New York <a class="header-anchor" href="#everyday-life-and-ordinary-new-york" aria-label="Permalink to &quot;Everyday Life and Ordinary New York&quot;">​</a></h1><p><strong>Research date: October 19, 2026.</strong> A card catalogue for making mundane life the main attraction: residents, pigeons, pets, lunch, newspapers, rent, homework, shops, tools, and public transportation. Marvel and Spider-Man are the starting point; other Magic settings and crossovers supply additional candidates.</p><p>The theme is what a card represents. An ordinary person&#39;s game ability can draw cards or grant counters without making that person a superhero. Likewise, <strong>School Daze</strong> qualifies through its homework premise even though it also has a Fight Crime mode. The actual rules of the card still apply. No card text, creature type, or format restriction is changed by appearing in this research.</p><p>This snapshot contains <strong>524 individually catalogued cards</strong>: <strong>97 Marvel entries</strong> and <strong>427 additional candidates</strong>. The fit labels comprise 125 Direct, 299 Setting, and 100 Almost entries. Ordinary-animal token examples are listed separately.</p><h2 id="browse-the-catalogue" tabindex="-1">Browse the catalogue <a class="header-anchor" href="#browse-the-catalogue" aria-label="Permalink to &quot;Browse the catalogue&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./everyday-life/marvel.html">Marvel and Spider-Man</a></td><td>Civilian characters, ordinary criminals, pets, objects, city locations, and everyday activities across Marvel printings.</td></tr><tr><td><a href="./everyday-life/people.html">People and ordinary jobs</a></td><td>Reporters, delivery workers, shopkeepers, medical staff, investigators, and other civilians from the rest of Magic.</td></tr><tr><td><a href="./everyday-life/animals.html">Pets, pests, and wildlife</a></td><td>Cats, dogs, pigeons, rats, squirrels, insects, pond animals, and broader farm/zoo/wildlife possibilities, including bears.</td></tr><tr><td><a href="./everyday-life/objects.html">Food, objects, and transportation</a></td><td>Meals, tools, household objects, recreation, and vehicles.</td></tr><tr><td><a href="./everyday-life/places-and-activities.html">Places and everyday activities</a></td><td>Streets, businesses, homes, errands, bills, school, social events, and ordinary crime. Includes instants, sorceries, enchantments, and lands.</td></tr><tr><td><a href="./everyday-life/almost-matches.html">Almost matches</a></td><td>Explicitly qualified exceptions such as Venomized Cat, supernatural pets, disguised heroes, animated household objects, and silver-bordered jokes.</td></tr><tr><td><a href="./everyday-life/tokens.html">Ordinary-animal tokens</a></td><td>Cards literally named Cat, Dog, Rat, Bird, Mouse, Squirrel, and Bear, with their specific token characteristics.</td></tr></tbody></table><p>Download the <a href="everyday-life/cards.csv">complete catalogue as CSV</a> for spreadsheet sorting, or the <a href="everyday-life/cards.json">structured JSON</a> for future project tools. These contain the same individual entries as the category pages, including exact card names, types, set/collector identifiers, mana costs, colors, fit judgments, notes, and Scryfall links. The token examples have their own page and are not mixed into the regular-card download.</p><h2 id="how-the-fit-labels-work" tabindex="-1">How the fit labels work <a class="header-anchor" href="#how-the-fit-labels-work" aria-label="Permalink to &quot;How the fit labels work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Label</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Direct</strong></td><td>A strong ordinary-life premise that can fit the city joke: a person at work, a pet, a meal, a real object, or an everyday activity. A superhero can appear in the surrounding story without disqualifying the ordinary subject.</td></tr><tr><td><strong>Setting</strong></td><td>The person, animal, object, or activity is ordinary, but the era, habitat, species&#39; real-world range, artwork, or franchise is less suited to present-day New York. A bear belongs here because it is ordinary wildlife, not normal subway wildlife.</td></tr><tr><td><strong>Almost</strong></td><td>Something specifically extraordinary is part of the subject: powers, a transformation, an alien infection, an animated object, an anthropomorphic fantasy species, or special joke-card rules. Every such row explains the exception.</td></tr></tbody></table><p>These are editorial judgments, not official Scryfall categories or legality labels. Some borderline choices will reasonably move after looking at the cards together. <strong>Venomized Cat</strong> is deliberately included: the joke of a little cat that caught alien goo survives, while its Symbiote Cat Villain identity remains explicit.</p><h2 id="particularly-useful-starting-points" tabindex="-1">Particularly useful starting points <a class="header-anchor" href="#particularly-useful-starting-points" aria-label="Permalink to &quot;Particularly useful starting points&quot;">​</a></h2><p>For the ordinary New York idea, begin with <strong>City Pigeon</strong>, <strong>Aunt May</strong>, <strong>J. Jonah Jameson</strong>, <strong>Gallant Citizen</strong>, <strong>Selfless Police Captain</strong>, <strong>Daily Bugle Reporters</strong>, <strong>Supportive Parents</strong>, <strong>Common Crook</strong>, <strong>Taxi Driver</strong>, and <strong>Willie Lumpkin, Postman</strong>. The noncreature side is just as central: <strong>Bagel and Schmear</strong>, <strong>Hot Dog Cart</strong>, <strong>Daily Bugle Newspaper</strong>, <strong>Peter Parker&#39;s Camera</strong>, <strong>News Helicopter</strong>, <strong>Subway Train</strong>, <strong>Passenger Ferry</strong>, <strong>Rent Is Due</strong>, <strong>School Daze</strong>, and <strong>Urban Retreat</strong>.</p><p>Outside Marvel, <strong>Courier of Comestibles</strong>, <strong>Action News Crew</strong>, <strong>Skateboard</strong>, <strong>Manhole Cover</strong>, <strong>Big Apple, 3 a.m.</strong>, and the TMNT pizza cards bring useful modern-city material. <strong>Dog Walker</strong>, <strong>Citizen&#39;s Crowbar</strong>, <strong>Jackhammer</strong>, <strong>Tramway Station</strong>, and <strong>Getaway Car</strong> offer strong ordinary roles and objects from fantasy cities. <strong>Sanctuary Cat</strong>, <strong>Helpful Hunter</strong>, <strong>Warehouse Tabby</strong>, <strong>Selfless Savior</strong>, <strong>Carrier Pigeons</strong>, <strong>Sewer Rats</strong>, and <strong>Brood of Cockroaches</strong> make the animal side substantial enough to explore without turning it into a collection of superheroes.</p><p>The names above are entry points, not a proposed decklist. The linked category pages preserve the much larger card-by-card catalogue.</p><h2 id="rules-distinctions-that-matter-when-building" tabindex="-1">Rules distinctions that matter when building <a class="header-anchor" href="#rules-distinctions-that-matter-when-building" aria-label="Permalink to &quot;Rules distinctions that matter when building&quot;">​</a></h2><p><strong>News Helicopter is an artifact creature — Construct.</strong> It is not a Vehicle, despite depicting a helicopter. <strong>Subway Train</strong> and <strong>Passenger Ferry</strong> are Vehicles and are not creature cards in the deck. <strong>J. Jonah Jameson</strong> and <strong>Aunt May</strong> are Human Citizens, <strong>Selfless Police Captain</strong> is a Human Detective, and <strong>City Pigeon</strong> is a Bird. A shared city theme does not make them share a creature type.</p><p>For <a href="./../formats/creature-feature/rules.html">Creature Feature</a>, count the actual types and the complete deck-construction requirements. Human could connect many of the people, with birds or other non-Humans using the permitted support space; Citizen is a narrower choice. This reference does not authorize treating all residents as Citizens or all animals as one type.</p><p>Keep full modal cards and both faces where applicable. Including <strong>School Daze</strong> for Do Homework does not remove Fight Crime. A box that changes a rule must deliberately document the change against its chosen base format. The same care applies to Horde targeting, optional abilities, repeat activations, and effects that require a player to make decisions.</p><p>The project&#39;s usual preference remains distinct nonbasic cards. Some candidates explicitly reward repeated names—such as <strong>Gathering Throng</strong>, <strong>Squadron Hawk</strong>, <strong>Pack Mastiff</strong>, and <strong>Relentless Rats</strong>. Their notes make that visible; inclusion in a catalogue does not commit a box to duplicates. Basic lands and token quantities follow the selected game&#39;s rules and actual component needs.</p><h2 id="coverage-and-research-method" tabindex="-1">Coverage and research method <a class="header-anchor" href="#coverage-and-research-method" aria-label="Permalink to &quot;Coverage and research method&quot;">​</a></h2><p>This is a <strong>best-effort discovery catalogue, not a claim to have found every possible mundane image ever printed</strong>. There is no reliable single query for this theme. Names alone miss ordinary scenes on abstractly named spells, while a Human or Cat type alone does not prove that a character is unpowered or an animal is mundane.</p><p>The search combined:</p><ol><li>A broad pass through the released Marvel-art card pool, including SPM, SPE, MSH, MSC, MAR, and Marvel Secret Lair material. See the separate <a href="./marvel-card-pools.html">Marvel set reference</a> for the complete code inventory.</li><li>The TMNT card pools and targeted passes through New Capenna, Karlov Manor, Neon Dynasty, Fallout, and Doctor Who for city life, civilians, and contemporary objects.</li><li>Cross-set creature searches for Citizens, ordinary pets, birds, rats, squirrels, bears, other animals, and common insect/pest names. Obvious anthropomorphic heroes, spirits, and monsters were excluded or moved to Almost.</li><li>Food and Vehicle searches, plus grouped name searches for occupations, household tools, transport, places, money problems, meals, school, leisure, maintenance, and crime. This explicitly included noncreature cards.</li><li>Exact-name checks, Oracle-type and rules-text review, and selected artwork checks for ambiguous candidates. Each row links a specific printing so that visual fit can be reviewed before selecting the physical cards. The catalogue does not claim that every alternate artwork was inspected.</li></ol><p>Card facts were retrieved through the project&#39;s <a href="https://github.com/cryppadotta/scryfall-mcp" target="_blank" rel="noreferrer">Scryfall MCP server</a>. Searches used a release cutoff of <code>date&lt;=2026-10-19</code>; token and art-card records were separated from the ordinary-card list. Large result sets were divided into smaller queries rather than treating the first result page as the entire pool.</p><p>The <a href="everyday-life/searches.json">saved search log</a> records the successful search families and their scopes. It is a reproducibility aid, not a second uncurated recommendation list. Search results overlap, and a record count is not a count of separate recommended cards.</p><h3 id="useful-repeatable-searches" tabindex="-1">Useful repeatable searches <a class="header-anchor" href="#useful-repeatable-searches" aria-label="Permalink to &quot;Useful repeatable searches&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Discovery task</th><th>Scryfall search</th></tr></thead><tbody><tr><td>All Marvel artwork</td><td><a href="https://scryfall.com/search?q=art%3Amarvel-comics+date%3C%3D2026-10-19" target="_blank" rel="noreferrer">Marvel card pool</a></td></tr><tr><td>Marvel&#39;s people outside the obvious Hero/Villain types</td><td><a href="https://scryfall.com/search?q=art%3Amarvel-comics+t%3Ahuman+-t%3Ahero+-t%3Avillain" target="_blank" rel="noreferrer">Human creatures without those two types</a> — also inspect Heroes/Villains manually; Night Nurse and Common Crook show why this filter is incomplete.</td></tr><tr><td>Citizen creatures across Magic</td><td><a href="https://scryfall.com/search?q=t%3Acitizen+t%3Acreature" target="_blank" rel="noreferrer">Citizens</a> — includes nonhuman and transformed residents.</td></tr><tr><td>Cats, dogs, rats, and mice</td><td><a href="https://scryfall.com/search?q=%28t%3Acat+or+t%3Adog+or+t%3Arat+or+t%3Amouse%29+t%3Acreature" target="_blank" rel="noreferrer">Pet and pest types</a> — includes monsters and anthropomorphic characters to screen out.</td></tr><tr><td>Actual Food objects</td><td><a href="https://scryfall.com/search?q=t%3Afood+-t%3Atoken" target="_blank" rel="noreferrer">Food cards</a> — some are living Food creatures or magical meals.</td></tr><tr><td>Transportation</td><td><a href="https://scryfall.com/search?q=t%3Avehicle" target="_blank" rel="noreferrer">Vehicles</a> — also search names; News Helicopter demonstrates why Vehicle alone is incomplete.</td></tr><tr><td>Literally Cat</td><td><a href="https://scryfall.com/search?q=%21%22Cat%22+t%3Atoken+include%3Aextras+unique%3Aprints" target="_blank" rel="noreferrer">Cat tokens</a> — a token search, not permission to put tokens into an ordinary deck.</td></tr></tbody></table><p>When extending the list, record the <strong>full card name</strong>, a particular printing, the actual type line, the fit label, and the reason. Preserve almost-match explanations. A named character&#39;s civilian job, an alternate artwork, or an ordinary-sounding title can be worth considering without silently erasing the extraordinary part.</p>',28)])])}const u=t(o,[["render",n]]);export{p as __pageData,u as default};
